from typing import Any, Dict, List, Optional
from pydantic import BaseModel, ConfigDict, Field


class ContextQuestion(BaseModel):
    """Question generated by KIE to clarify learner context."""
    model_config = ConfigDict(extra="ignore")

    question_id: str
    text: str
    type: str = "single_select"  # "multi_select" or "single_select"
    options: List[str] = Field(default_factory=list)


class AnalyzeContextRequest(BaseModel):
    """
    Inbound request from Backend: POST /api/v1/kie/context/analyze or /api/v1/kie/roadmap/generate
    Backend passes the full ContextV2 payload.
    Backend sends either learner_id or user_id (or both).
    """
    model_config = ConfigDict(extra="allow")

    learner_id: Optional[str] = None
    user_id: Optional[str] = None
    scope: Optional[str] = "ACADEMIC"
    target_subject: Optional[str] = None          # When generating a dedicated subject track
    selected_subjects: Optional[List[str]] = None  # Subset of subjects to include
    learner: Optional[Dict[str, Any]] = None
    education: Optional[Dict[str, Any]] = None
    preferences: Optional[Dict[str, Any]] = None
    syllabus: Optional[Dict[str, Any]] = None
    roadmap: Optional[Dict[str, Any]] = None
    recent_history: Optional[List[Dict[str, Any]]] = None
    memory_summary: Optional[Dict[str, Any]] = None


class AnalyzeContextResponse(BaseModel):
    """Immediate acknowledgement returned to Backend."""
    status: str = "processing"
    questions: List[ContextQuestion] = Field(default_factory=list)


class ContextAnswerItem(BaseModel):
    """An answer item submitted by the learner."""
    model_config = ConfigDict(extra="allow")

    question_id: str
    answer: Any


class ResolveContextRequest(BaseModel):
    """
    Inbound request from Backend: POST /api/v1/kie/context/resolve
    Carries user_id and list of answers.
    """
    model_config = ConfigDict(extra="allow")

    user_id: Optional[str] = None
    learner_id: Optional[str] = None
    answers: List[ContextAnswerItem] = Field(default_factory=list)


class ResolveContextResponse(BaseModel):
    """Immediate acknowledgement returned to Backend."""
    status: str = "ok"
    new_context: Dict[str, Any] = Field(default_factory=dict)


class WebhookQuestionsPayload(BaseModel):
    """Outbound payload sent to Backend: POST /api/v1/onboarding/kie/webhook/questions"""
    user_id: str
    questions: List[ContextQuestion]


class WebhookResolvedPayload(BaseModel):
    """Outbound payload sent to Backend: POST /api/v1/onboarding/kie/webhook/resolved"""
    user_id: str
    new_context: Dict[str, Any]

